package app.layan.quran;
import android.app.Activity;import android.content.Intent;import android.view.*;
/** Hooks only the original toolbar. The original reader and swipe code are unchanged. */
public final class LayanBridge {
 public static final int HADITH=0x4c590001,PRAYER=0x4c590002,AZKAR=0x4c590003,QIBLA=0x4c590004,VERSES=0x4c590005,QIRAAT=0x4c590006,NIYYAH=0x4c590007;
 public static void addMenu(Activity activity,Menu menu){tintMenu(activity,menu);menu.add(0,HADITH,0,"الأحاديث").setShowAsAction(MenuItem.SHOW_AS_ACTION_NEVER);menu.add(0,PRAYER,1,"الصلاة").setShowAsAction(MenuItem.SHOW_AS_ACTION_NEVER);menu.add(0,AZKAR,2,"الأذكار").setShowAsAction(MenuItem.SHOW_AS_ACTION_NEVER);menu.add(0,QIBLA,3,"القبلة").setShowAsAction(MenuItem.SHOW_AS_ACTION_NEVER);boolean ar=activity.getResources().getConfiguration().getLocales().get(0).getLanguage().equals("ar")||android.preference.PreferenceManager.getDefaultSharedPreferences(activity).getBoolean("useArabicNames",false);menu.add(0,QIRAAT,4,ar?"القراءات العشر":"Ten readings").setShowAsAction(MenuItem.SHOW_AS_ACTION_NEVER);menu.add(0,NIYYAH,5,ar?"النوايا":"Intentions").setShowAsAction(MenuItem.SHOW_AS_ACTION_NEVER);}
 public static void addReaderMenu(Activity activity,Menu menu){tintMenu(activity,menu);boolean ar=android.preference.PreferenceManager.getDefaultSharedPreferences(activity).getBoolean("useArabicNames",false)||activity.getResources().getConfiguration().getLocales().get(0).getLanguage().equals("ar");menu.add(0,VERSES,4,ar?"القراءة بالآيات":"Read by ayah").setShowAsAction(MenuItem.SHOW_AS_ACTION_NEVER);}
 private static void tintMenu(Activity activity,Menu menu){android.content.res.ColorStateList tint=android.content.res.ColorStateList.valueOf(new LayanUi.Palette(activity).green);for(int i=0;i<menu.size();i++)if(menu.getItem(i).getIcon()!=null)menu.getItem(i).setIconTintList(tint);}
 public static void openVerses(Activity activity,int page){activity.startActivity(new Intent(activity,VerseReadingActivity.class).putExtra("page",page));}
 public static boolean handle(Activity activity,MenuItem item){Class<?> target;if(item.getItemId()==HADITH)target=HadithActivity.class;else if(item.getItemId()==PRAYER)target=PrayerActivity.class;else if(item.getItemId()==AZKAR)target=AzkarActivity.class;else if(item.getItemId()==QIBLA)target=QiblaActivity.class;else if(item.getItemId()==VERSES)target=VerseReadingActivity.class;else if(item.getItemId()==QIRAAT)target=QiraatActivity.class;else if(item.getItemId()==NIYYAH)target=NiyyahActivity.class;else return false;activity.startActivity(new Intent(activity,target));return true;}
}
